/* Demo access links separate the organizer portal from each guest portal. */
'use strict';
const portalBase={render,handle,header:guestHeader,bar:demoBar};
const portalRole=()=>state.ui.portalRole||(state.ui.guest==='organizer'?'organizer':'guest');
const portalGuest=()=>{if(!state.pickup)return null;const id=state.ui.portalGuestId||pickup().lastBooking;if(id?.startsWith('slot-'))return organizerPaidGuest(slotById(id));return individualById(id);};
function organizerPaidGuest(slot){if(!slot?.guest)return null;slot.guestPortal??={id:'00031',guest:slot.guest,type:slot.type,unit:slot.unit,status:'Confirmed',paid:true,organizerPaid:true,amount:roomTotal(slot.type),activities:[],assigned:true};if(slot.guestPortal.id==='00031')slot.guestPortal.id=String(pickup().nextId++).padStart(5,'0');Object.assign(slot.guestPortal,{slotId:slot.id,guest:slot.guest,type:slot.type,unit:slot.unit});return slot.guestPortal;}
const portalEvents=()=>state.quote?.notes||[];
const portalMenus={organizer:[['Group overview','overview'],['Room allocation','rooms'],['Guest list','guests'],['BEO / contract','documents'],['Invoices & balance','billing'],['Schedule / meals','schedule']],guest:[['My stay','stay'],['Confirm room','room'],['Payment','payment'],['Schedule','schedule'],['Documents','documents'],['Charges','charges'],['Activities & extras','extras']]};
function portalHeader(){const role=portalRole();return '<header class="guest-header">'+img('0d92a.svg','Booking Ninjas')+'<div class="portal-person"><strong>'+ (role==='organizer'?'Organizer portal':'Guest portal')+'</strong><small>'+esc(role==='organizer'?name():portalGuest()?v2Full(portalGuest().guest):pickup()?.guestDraft?v2Full(pickup().guestDraft)||'Your group stay':'Your group stay')+'</small></div></header><nav class="portal-menu" aria-label="'+role+' portal navigation">'+portalMenus[role].map(([title,key])=>'<button class="'+(state.ui.portalPage===key?'active':'')+'" data-action="portal-'+role+'-'+key+'">'+title+'</button>').join('')+'</nav>';}
guestHeader=function(){const view=state.ui.guest;const secure=state.ui.portalRole&&!['form','received','email','guest-inbox'].includes(view);return secure?portalHeader():portalBase.header();};
function openOrganizerPortal(page='overview'){state.ui.portalRole='organizer';state.ui.portalPage=page;modal=null;navigate('guest',page==='rooms'&&v2Active()?'organizer':'organizer-portal');}
function openGuestPortal(page='stay',id){if(id)state.ui.portalGuestId=id;state.ui.portalRole='guest';state.ui.portalPage=page;modal=null;if(v2Active()&&page==='payment'&&portalGuest()&&!portalGuest().paid){const r=portalGuest();pickup().invitedSlot=r.slotId;pickup().selectedType=r.type;pickup().guestDraft={...r.guest};navigate('guest','individual-payment');}else if(v2Active()&&!portalGuest()&&['stay','room','payment'].includes(page))navigate('guest','group-code');else navigate('guest','guest-portal');}
function scheduleContent(){return '<div class="portal-agenda">'+[['Arrival & check-in','Nov 12 · 3:00–5:00 PM','Main Lodge Lobby'],['Leadership sessions','Nov 13–14 · 9:00 AM–5:00 PM','Meeting Hall'],['Group dinner','Each evening · 6:30–8:30 PM','Dining Hall'],['Breakfast','Nov 13–15 · 7:30–9:00 AM','Dining Hall'],['Departure','Nov 15 · 11:00 AM','Main Lodge Lobby']].map(([title,time,place])=>'<article><div><h3>'+title+'</h3><p>'+time+'</p></div><span>'+place+'</span></article>').join('')+'</div>';}
function organizerPortal(){const page=state.ui.portalPage||'overview',r=state.request,q=state.quote,t=totals();let body='';
 if(page==='overview'){body='<div class="pickup-confirmed-columns">'+panel('Group overview','<div class="grid2">'+detail('Group',esc(r.group))+detail('Status',badge(state.reservation?.status||q.status))+detail('Dates',dates())+detail('Guests',r.guests)+detail('Rooms blocked',requestedRoomCount(r))+detail('Group code','GBR-008')+'</div><div class="row mt">'+(q.status==='Sent'?button('Review your quote','review-quote','primary'):button('View contract','doc-contract'))+(state.reservation?.status==='Confirmed'?button('Assign your rooms','portal-organizer-rooms','primary'):'')+'</div>')+panel('Your booking',line('Original booking total',money(t.total))+line('Deposit received',money(q.paid?t.deposit:0))+line('Balance due',money(v2Active()?groupInvoiceTotal()-t.deposit:t.total-(q.paid?t.deposit:0)))+'<p class="hint mt">Balance due '+dueDate()+'.</p>')+'</div>'+(q.signature&&!q.paid?'<div class="mt">'+button('Pay group deposit','portal-deposit','primary')+'</div>':'');}
 else if(page==='rooms'){body=panel('Room allocation',state.reservation?.status==='Confirmed'?'<p>Your confirmed group is ready for guest assignments.</p>'+button('Open room allocation','portal-start-pickup','primary'):'<p>Room allocation becomes available once the venue confirms the group reservation.</p>');}
 else if(page==='guests'){const slots=v2Active()?roomSlots().filter(s=>s.guest):[];body=panel('Guest list',slots.length?table(['GUEST','EMAIL','ROOM','WHO PAYS','STATUS'],slots.map(s=>[esc(v2Full(s.guest)),esc(s.guest.email),esc(s.type),s.payer,v2Pill(s.status)])):'<p class="muted">No guests assigned yet.</p>',v2Active()?button('Add guest','v2-add','primary'):'');}
 else if(page==='documents'){body='<div class="grid2">'+documentCard('beo')+documentCard('contract')+'</div>';}
 else if(page==='billing'){const credit=v2Active()?pickupCredit():0,total=t.total-credit;body=panel('Group invoice',line('Original group booking',money(t.total))+(credit?line('Individual room credits','−'+money(credit)):'')+line('Organizer invoice',money(total),'total')+line('Deposit paid',money(q.paid?t.deposit:0))+line('Balance due',money(total-(q.paid?t.deposit:0)))+'<p class="hint">Due '+dueDate()+'. Guest room payments are credited to the group invoice.</p>',state.reservation?button('Download invoice','download-invoice'):q.signature&&!q.paid?button('Pay deposit','portal-deposit','primary'):'');}
 else if(page==='schedule'){body=panel('Schedule & meals',scheduleContent()+'<p class="hint mt">Group catering includes three daily meals for '+r.guests+' guests.</p>');}
 return v2Page(v2Title(page==='overview'?'Your group booking':portalMenus.organizer.find(x=>x[1]===page)?.[0]||'Your group',esc(r.group)+' · '+dates())+body,true);
}
const extraCatalog=[{id:'yoga',title:'Morning yoga',description:'Nov 13 · 7:00 AM · Garden Studio',price:25},{id:'shuttle',title:'Airport shuttle',description:'Nov 12 · 1:00 PM · Arrival transfer',price:35},{id:'meal',title:'Packed lunch for departure',description:'Nov 15 · Pick up before check-out',price:18},{id:'walk',title:'Guided nature walk',description:'Nov 14 · 4:00 PM · Main Lodge',price:20}];
const guestExtras=r=>(r.extras||[]).map(id=>extraCatalog.find(x=>x.id===id)).filter(Boolean);
const extrasTotal=r=>Math.round(guestExtras(r).reduce((n,x)=>n+x.price,0)*1.1*100)/100;
const portalIndividualBase=individualDetailPage;
individualDetailPage=function(){let html=portalIndividualBase();const r=currentIndividual(),extra=extrasTotal(r);if(!extra)return html;const total=r.amount+extra,balance=(r.paid?0:r.amount)+extra-(r.extrasPaid||0);html=html.replace('<span>Grand Total</span><strong>'+money(r.amount),'<span>Grand Total</span><strong>'+money(total)).replace('<span>Balance Due</span><strong>'+money(r.paid?0:r.amount),'<span>Balance Due</span><strong>'+money(balance));if((pickup().detailTab||'Details')==='Details')html=html.replace('<div class="reservation-add">','<h2 class="reservation-section-title">Guest extras</h2>'+table(['EXTRA','SCHEDULE','AMOUNT','PAYMENT'],guestExtras(r).map(x=>[x.title,x.description,money(x.price*1.1),r.extrasPaid>=extra?badge('Paid'):badge('Pending')]))+'<div class="reservation-add">');return html;};
function guestPortal(){const page=state.ui.portalPage||'stay',r=portalGuest();if(!r)return v2Page(v2Title('Your group stay','Use your invitation link or the group code to reserve a room.')+button('Enter group code','v2-code','primary'));let body='';
 if(page==='stay'||page==='room'){body='<div class="pickup-confirmed-columns">'+panel(page==='room'?'Your assigned room':'My stay','<div class="grid2">'+detail('Guest',esc(v2Full(r.guest)))+detail('Reservation','#'+r.id)+detail('Room',esc(r.type))+detail('Room number',r.assigned?r.unit:'Assigned at check-in')+detail('Dates',dates())+detail('Status',badge(r.status))+'</div><div class="row mt">'+(!r.paid?button('Confirm and pay','portal-guest-payment','primary'):page==='room'&&!r.roomAccepted?button('Confirm room','portal-confirm-room','primary'):button('Download confirmation','portal-download'))+'</div>'+(r.roomAccepted?'<p class="hint mt">Room confirmed by you.</p>':''))+panel('Your retreat',scheduleContent())+'</div>';}
 else if(page==='payment'||page==='charges'){const extras=extrasTotal(r);body=panel(page==='payment'?'Payment':'Your charges',line(esc(r.type)+' × '+nights()+' nights',money(roomRate(r.type)*nights()))+line('Room taxes',money(r.amount-roomRate(r.type)*nights()))+line('Room total',money(r.amount),'total')+line(r.organizerPaid?'Paid by organizer':'Room paid',money(r.paid?r.amount:0))+(extras?guestExtras(r).map(x=>line(x.title,money(x.price))).join('')+line('Extras tax',money(extras-guestExtras(r).reduce((n,x)=>n+x.price,0)))+line('Extras paid',money(r.extrasPaid||0)):'')+line('Balance due',money((r.paid?0:r.amount)+extras-(r.extrasPaid||0)))+(extras>(r.extrasPaid||0)?button('Pay extras '+money(extras-(r.extrasPaid||0)),'portal-pay-extras','primary'):'')+'<p class="hint mt">Demo payments only; no charge is made.</p>');}
 else if(page==='schedule'){body=panel('Your schedule',scheduleContent()+guestExtras(r).map(x=>'<article class="guest-extra-schedule"><h3>'+x.title+'</h3><p>'+x.description+'</p></article>').join(''));}
 else if(page==='documents'){body=panel('Your documents','<div class="file-item"><div><b>Reservation confirmation · #'+r.id+'</b><p class="hint">Your room, dates and payment</p></div>'+button('Download','portal-download')+'</div><div class="file-item"><div><b>Retreat schedule</b><p class="hint">Meeting sessions and group meals</p></div>'+button('View','portal-guest-schedule')+'</div>');}
 else if(page==='extras'){body='<div class="grid2">'+extraCatalog.map(x=>panel(x.title,'<p class="muted">'+x.description+'</p><p class="mt"><b>'+money(x.price)+'</b> + 10% tax</p>',button(r.extras?.includes(x.id)?'Added':'Add','portal-extra-'+x.id,r.extras?.includes(x.id)?'':'primary',r.extras?.includes(x.id)))).join('')+'</div><div class="mt">'+button('Review charges','portal-guest-charges','primary')+'</div>';}
 return v2Page(v2Title(portalMenus.guest.find(x=>x[1]===page)?.[0]||'My stay',esc(state.request.group)+' · Reservation #'+r.id)+body);
}
render=function(){if(state.ui.app==='guest'&&['organizer-portal','guest-portal'].includes(state.ui.guest)){$('#demo').innerHTML=demoBar();$('#app').innerHTML=state.ui.guest==='organizer-portal'?organizerPortal():guestPortal();renderOverlay();return;}portalBase.render();};
demoBar=function(){let html=portalBase.bar();html=html.replaceAll('Guest App','Guest Portals');if(v2Active())html=html.replace('>Organizer</button>','>Organizer link</button>').replace('>Book with group code</button>','>Guest link</button>').replace('>Guest inbox</button>','>Demo inbox</button>');return html;};
handle=function(a,el){try{
 if(a==='v2-organizer'){return openOrganizerPortal('rooms');}
 if(a==='v2-code'){state.ui.portalRole='guest';state.ui.portalPage='stay';state.ui.portalGuestId=null;return portalBase.handle(a,el);}
 if(a==='v2-sample'){portalBase.handle(a,el);state.ui.portalRole='organizer';state.ui.portalPage='rooms';save();render();return;}
 if(a==='v2-current'){portalBase.handle(a,el);state.ui.portalRole='organizer';state.ui.portalPage='rooms';save();render();return;}
 if(a==='review-quote'){state.ui.portalRole='organizer';state.ui.portalPage='documents';return portalBase.handle(a,el);}
 if(a.startsWith('v2-invitation-')){state.ui.portalRole='guest';state.ui.portalPage='payment';state.ui.portalGuestId=a.slice(14);return portalBase.handle(a,el);}
 if(a==='v2-pay'){portalBase.handle(a,el);if(state.ui.guest==='individual-confirmed'){state.ui.portalGuestId=pickup().lastBooking;state.ui.portalPage='stay';save();render();}return;}
 if(a==='my-booking'&&state.ui.portalRole){return portalRole()==='organizer'?openOrganizerPortal():openGuestPortal();}
 if(a.startsWith('portal-organizer-')){const page=a.slice(17);return openOrganizerPortal(page);}
 if(a.startsWith('portal-guest-')){return openGuestPortal(a.slice(13));}
 if(a==='portal-deposit'){state.ui.portalRole='organizer';navigate('guest','payment');return;}
 if(a==='portal-start-pickup'){requireState(state.reservation?.status==='Confirmed','Wait for venue confirmation.');if(!state.pickup)setupPickup(false);pickup().active=true;state.ui.video=2;return openOrganizerPortal('rooms');}
 if(a==='portal-confirm-room'){const r=portalGuest();requireState(r?.paid,'Complete the room payment first.');r.roomAccepted=true;r.activities??=[];r.activities.push('Guest confirmed their room.');save();render();toast('Your room is confirmed.');return;}
 if(a==='portal-download'){downloadIndividualPDF(portalGuest());return;}
 if(a.startsWith('portal-extra-')){const r=portalGuest();requireState(r?.paid,'Confirm your room before adding extras.');const id=a.slice(13);requireState(extraCatalog.some(x=>x.id===id),'Extra not found.');r.extras??=[];if(!r.extras.includes(id))r.extras.push(id);r.activities.push('Guest added '+extraCatalog.find(x=>x.id===id).title+'.');save();render();toast('Added to your stay and charges.');return;}
 if(a==='portal-pay-extras'){const r=portalGuest();r.extrasPaid=extrasTotal(r);r.activities.push('Guest paid extras with demo payment.');save();render();toast('Payment received for your extras.');return;}
 return portalBase.handle(a,el);
 }catch(e){toast(e.message,true);}};
const portalQuery=new URLSearchParams(location.search);if(portalQuery.get('access')==='organizer'&&state.quote){state.ui.portalRole='organizer';state.ui.portalPage='overview';state.ui.app='guest';state.ui.guest='organizer-portal';}else if(portalQuery.get('access')==='guest'&&v2Active()){state.ui.portalRole='guest';const id=portalQuery.get('reservation');if(id&&individualById(id)){state.ui.portalGuestId=id;state.ui.portalPage='stay';state.ui.app='guest';state.ui.guest='guest-portal';}else{state.ui.guest='group-code';state.ui.app='guest';pickup().codeApplied=portalQuery.get('group')==='GBR-008';}}
render();
